={
  "model": "claude-opus-4-6",
  "max_tokens": 1200,
  "messages": [{
    "role": "user",
    "content": "Analyze this {{ $json.call_type }} call transcript and generate a structured summary.

Call Details:
- Agent: {{ $json.agent_name }}
- Customer: {{ $json.customer_name }}
- Duration: {{ $json.call_duration }} minutes
- Type: {{ $json.call_type }}

TRANSCRIPT:
{{ $json.transcript }}

Generate a JSON summary with these exact fields:
{
  "one_line_summary": "",
  "issues_discussed": [],
  "resolutions": [],
  "action_items": [{"owner": "", "task": "", "due": ""}],
  "customer_sentiment": "positive|neutral|negative",
  "customer_satisfaction_score": 1-10,
  "escalation_needed": true/false,
  "escalation_reason": "",
  "crm_notes": "CRM-ready paragraph under 100 words",
  "follow_up_date": "YYYY-MM-DD or null",
  "key_quotes": []"
  }]
}

parameters.jsCode:
const raw = $input.first().json.content[0].text;
let summary;
try {
  summary = JSON.parse(raw);
} catch (e) {
  const match = raw.match(/\{[\s\S]*\}/);
  try { summary = JSON.parse(match[0]); } catch { summary = { one_line_summary: raw.substring(0, 200), issues_discussed: [], resolutions: [], action_items: [], customer_sentiment: 'neutral', customer_satisfaction_score: 5, escalation_needed: false, escalation_reason: '', crm_notes: raw.substring(0, 300), follow_up_date: null, key_quotes: [] }; }
}

const call = $('Extract Call Data').first().json;
return [{ json: { ...summary, agent_name: call.agent_name, customer_name: call.customer_name, call_duration: call.call_duration, call_type: call.call_type, generated_at: new Date().toISOString() } }];

